function sumOf(text) {
  let h = 7;
  for (let i = 0; i < text.length; i++) h = (h * 31 + text.charCodeAt(i)) >>> 0;
  return h;
}
export function saveGame(game) {
  return JSON.stringify({ ...game, check: sumOf(JSON.stringify(game)) });
}

